/* La historia del mundo (versión 37, según la biblia v2): las criaturas, Nimba, Prisma, Tilde, la Abuela Brizna,
 * las páginas del diario de Tilo y lo que dicen los animales. Cada texto tiene su versión corta para el modo niño.
 * Regla: nadie dice el nombre de Tilo antes del final secreto; nadie habla de morir (se fue a dormir con las estrellas);
 * el secreto del huevo solo se insinúa (Brizna, Tilde) hasta que el Corazón la reconoce.
 * Lo incluye solo textos23.h (y este, solo pet.c). */

typedef struct { const char *titulo, *txt, *corto; } historia_t;

/* --- las criaturas: quiénes son (con su voz) --- */
static const char *const CRIATURA_NOMBRE[CRI_COUNT] = {"Musguito", "Lumbre", "Ondina", "Anemoi", "Cristalino", "Marea"};
static const char *const CRIATURA_SOBRE[CRI_COUNT] = {
    "Un duende de musgo del prado. Chiquito, verde y tan tímido que habla bajito. Plantó la primera semilla con el Cuidador. Dice «chiquito» todo el rato, porque cree que todo lo importante empieza así.",
    "Un hada de luz del Bosque de los Coihues. De día casi no se ve; de noche brilla como una luciérnaga grande. Habla lento, como quien mira la luna. Nunca deja a nadie caminar a oscuras.",
    "Un espíritu del agua que vive en la laguna. Antes fue una nube. Llora por todo y se ríe igual de fuerte: exagera, suspira, actúa. Peina a los peces con una concha y consuela como nadie.",
    "Anemoi, un dragón del viento del cerro, hermano de Prisma. Echa ráfagas de aire tibio y presume de ser el mejor volador del mundo. Aprendió a volar cayéndose, y no le da vergüenza contarlo. Bueno, un poco.",
    "Un gnomo de cristal de la cueva. Afina las piedras, ordena los ecos y se queja si algo suena medio tono abajo. Gruñón por fuera, tierno por dentro. Guarda cada nota que alguien cantó aquí.",
    "Una sirenita del faro de la isla. Habla poco y firme. Acompaña a todos en el bote, porque dice que nadie debería cruzar solo. Conoce el nombre de cada estrella y sabe esperar.",
};
/* lo que dicen cuando ya contaron todo, después del final secreto */
static const char *const CRIATURA_DESPUES[CRI_COUNT] = {
    "Ahora sabemos quién eras, Peumo. Chiquito… como yo.",
    "Peumo. Ahora tu luz tiene nombre.",
    "¡Peumo! ¡Se llamaba Peumo! Ay, voy a llorar. Ya lloré.",
    "¡Peumo, el segundo mejor volador del mundo! Después de mí.",
    "Peumo. Cinco letras. Afinadas.",
    "Peumo cruzó. Ahora nadie cruza solo.",
};

/* --- las historias de cada criatura: cinco cada una, en orden (acto 1: 1-2, acto 2: 3-4, acto 3: la quinta) --- */
static const historia_t HISTORIAS[CRI_COUNT][5] = {
    { /* Musguito: el prado. Tímido, bajito. Recuerda al Cuidador gigante. Enseña: todo empieza chiquito */
     {"La primera semilla",
      "Planté la primera semilla con el Cuidador. Era un gigante, ¿sabes? Cuando se agachaba, me tapaba el sol. Cavamos con una cuchara de palo y él dijo: «Todo empieza chiquito». Yo pensé que lo decía por mí… Ahora creo que lo decía por todo.",
      "Planté la primera semilla con el Cuidador. Me dijo: «Todo empieza chiquito». Como yo."},
     {"Las galletas del hueco",
      "En el hueco del árbol viejo, el Cuidador guardaba sus galletas de piñón con miel de ulmo. Siempre quemadas. Él decía que «así venían». Una mañana el árbol le devolvió una galleta dorada, perfecta… y chiquitita. Desde entonces las ofrendas se dejan ahí, y el árbol las cambia por algo bonito. El Cuidador se comió la galleta perfecta y dijo que estaba rica. Mentía: a él le gustaban quemadas.",
      "El árbol viejo le dio al Cuidador una galleta perfecta. Dijo que estaba rica… pero le gustaban quemadas."},
     {"Doña Pétalo y las demás",
      "De noche las flores se cierran para contarse cuentos. El Cuidador les cantaba para que se durmieran. Cantaba feo… pero con tantas ganas. A cada flor le puso un nombre larguísimo: esa es «Doña Pétalo Que Se Ríe Cuando Llueve». Se acostaba en el pasto para hablarles. Era tan grande… ¿o era yo el que se subía a una piedrita?",
      "El Cuidador les cantaba a las flores. Feo, pero con ganas. A cada una le puso un nombre larguísimo."},
     {"La cuchara perdida",
      "Cuando el sol y la lluvia peleaban, el Cuidador se paró entre los dos con su cuchara de palo, como dirigiendo una orquesta. «Pueden estar los dos», les dijo. Y salió el primer arcoíris. Esa tarde se le perdió la cuchara. Yo creo que sigue donde bailan las hadas… chiquitita, entre el musgo.",
      "El Cuidador hizo el primer arcoíris con su cuchara de palo. Después la perdió. Creo que está donde bailan las hadas."},
     {"La flor de la puerta",
      "Una vez le pregunté: «¿Y a ti quién te cuida?». Me hizo cosquillas y me contó el chiste de la papa. Siempre hacía eso. Esa noche le planté una flor en la puerta, chiquitita, para que supiera que alguien lo cuidaba. No sé si la vio. Si alguien quiere cuidarte… déjalo. Aunque sea chiquito como yo.",
      "Le pregunté quién lo cuidaba a él. Me contó un chiste. Si alguien quiere cuidarte, déjalo."}},
    { /* Lumbre: el bosque. Poética, lenta. Lo recuerda como una luz. Enseña: acompañar sin hablar también es cuidar */
     {"La chispa de cada una",
      "Las luciérnagas nacieron sin luz y le tenían miedo a la noche. El Cuidador subió al cerro y le pidió a la luna una chispa para cada una. Dicen que la luna se rio, porque le habló con la boca llena de galleta. Pero le dio las chispas. Desde entonces, ninguna camina a oscuras… y ninguna deja a nadie caminar a oscuras.",
      "El Cuidador le pidió a la luna una chispa para cada luciérnaga. Desde entonces, nadie camina a oscuras."},
     {"El pino que le temía a la noche",
      "El pino más viejo del bosque, de chiquito, le tenía miedo a la oscuridad. El Cuidador no sabía hacer luz. Así que hizo lo único que sabía: se sentó a su lado toda la noche y le contó chistes malos. Tan malos que el pino se reía de nervios… y se le olvidaba tener miedo. Yo vi una lucecita tibia junto al pino y me acerqué con la mía, sin decir nada. Desde esa noche, el pino nunca volvió a estar solo a oscuras. Ahora es tan alto que su punta toca las estrellas. Y de noche ronca: escúchalo, es el viento entre sus agujas.",
      "Al pino le daba miedo la noche. El Cuidador le contó chistes malos y yo llegué con mi luz. Ahora toca las estrellas."},
     {"La luz que llegaba primero",
      "Hay un sendero que cambia de lugar cada noche y siempre termina donde alguien necesita compañía. Yo nunca vi al Cuidador. Solo veía una luz tibia, chiquita, que iba por ese camino antes que nadie. Los otros dicen que tenía barba, voz, corona. Para mí era eso: una luz que llegaba primero a todo lo que dolía. Por eso le decían Rey.",
      "Yo nunca vi al Cuidador. Solo una luz chiquita que llegaba primero a todo lo que dolía."},
     {"La ronda de las hadas",
      "Con media luna, las hadas bailan en ronda. Es el baile que el Cuidador les enseñó… o intentó: las pisaba a todas. Igual lo dejaban en el centro. Una noche, bailando, se le cayó algo de madera entre el musgo, donde la ronda da vueltas. Las hadas lo cuidan desde entonces. Solo lo muestran a quien se queda a mirarlas, de noche y sin apuro.",
      "Al Cuidador se le cayó algo en el musgo, bailando. Las hadas lo cuidan. Míralas de noche, sin apuro."},
     {"La lucecita enferma",
      "Al final se enfermó, y su luz empezó a apagarse. De a poquito, como una lucecita enferma. Yo lo noté, y no dije nada. Pensé que acompañar sin hablar bastaba. A veces basta. Esa vez debí decirle: «Descansa. Ahora alumbramos nosotras». Si ves a alguien que se siente mal… díselo tú.",
      "Se enfermó y su luz se fue apagando. Yo no dije nada. Si ves a alguien enfermito, díselo: «ahora te cuido yo»."}},
    { /* Ondina: el lago. Dramática, llorona, divertida. Cree que lloró el lago sola. Enseña: llorar acompañado limpia */
     {"La nube llorona",
      "¿Sabes quién llenó la Laguna de los Cisnes? ¡Yo! Antes de ser espíritu del agua era una nube. Una nube muy, muy triste. Lloré tres días seguidos. ¡Tres! Yo solita, sin ayuda de nadie. Cuando terminé, me vi en el agua y dije: «Ay, pero qué bonita quedé». Y aquí me quedé a vivir.",
      "¡La laguna la lloré yo! Era una nube triste. Lloré tres días. Después me vi en el agua: ¡qué bonita!"},
     {"El pez dorado ofendido",
      "En la laguna vive un pez dorado que concede deseos chiquitos si lo dejas volver al agua. El Cuidador lo pescó una vez y lo soltó sin pedir nada. ¡Nada! El pez se ofendió tanto que todavía, cuando alguien lo suelta, concede dos deseos: uno para quien lo suelta y otro para el Cuidador, que nunca pidió nada para él.",
      "El Cuidador soltó al pez dorado sin pedir nada. ¡El pez todavía está ofendido!"},
     {"Las camitas de las ranas",
      "Los nenúfares son las camitas de las ranas. Los inventó el Cuidador porque no soportaba que nadie durmiera sin cama. ¡Y él no tenía cama! Dormía donde lo pillaba la noche. La garza dice que era altísimo. Pero yo lo vi sentado en un nenúfar… y el nenúfar ni se hundió. ¡Qué raro! ¿O no?",
      "El Cuidador inventó camitas para las ranas. Una vez se sentó en un nenúfar y no se hundió. ¿Raro, no?"},
     {"Las seis estrellas del agua",
      "De noche aparecen en la laguna estrellas que no están en el cielo. El Cuidador las dibujó con el dedo, una por cada manera de consolar: la tetera, el caracol, el farol, el pez, la escoba y el abrazo. Me las enseñó llorando de risa, porque se equivocaba de dedo. Si miras el agua con cariño, quizás aparezcan.",
      "El Cuidador dibujó en la laguna seis maneras de consolar. Míralo de noche, con cariño."},
     {"Llorar acompañada",
      "Te mentí. Bueno, exageré. La laguna no la lloré sola. Cuando era nube, el Cuidador se sentó a mi lado… y lloró conmigo. Los tres días. Nunca le pregunté por qué. Ahora pienso que él también necesitaba llorar, y no tenía con quién. Llorar acompañado limpia. Llorar solo… solo moja.",
      "No lloré sola: el Cuidador lloró conmigo. Él también necesitaba a alguien. Llorar acompañado limpia."}},
    { /* Anemoi: la colina. Aventurero, exagerado, presume. "Me enseñó a volar". Enseña: equivocarse es parte de aprender */
     {"De dónde viene el viento",
      "¡El viento lo invento yo! Bueno, casi. Nace en la cima del Cerro del Viento, cuando las nubes bostezan al despertar. Yo solo les hago cosquillas para que bostecen más grande. El Cuidador subía a sentirlo en la cara, con los ojos cerrados y la boca abierta. Una vez se tragó una hoja. Dijo que estaba rica. Mentía fatal.",
      "El viento nace cuando las nubes bostezan. El Cuidador lo sentía con la boca abierta. ¡Se tragó una hoja!"},
     {"Señor Don Gigante",
      "La roca grande se llama «Señor Don Gigante Que Mira El Atardecer Sin Apuro». Se lo puso el Cuidador: ¡le ponía nombres larguísimos a todo! A mí me decía «Anemoi El Que Todavía No Vuela Pero Ya Verás». Le dejaba su abrigo a la roca para que no tuviera frío. Al Don Gigante le quedaba chico. Y al Cuidador… le quedaba enorme.",
      "La roca se llama «Señor Don Gigante Que Mira El Atardecer Sin Apuro». El Cuidador le prestaba su abrigo."},
     {"Las cometas que se van",
      "El Cuidador hacía cometas y las soltaba todas. ¡Todas! Yo le decía: «¡Quédate una, aunque sea la fea!». Él decía que lo que se cuida de verdad aprende a volar solo. Ahora viven con las nubes. Si un día de viento sostienes una bien arriba y cuentas hasta treinta, baja trayendo algo de lejos. Yo cuento más rápido, pero no funciona.",
      "El Cuidador soltaba todas sus cometas. Un día de viento, sostén una arriba: baja con algo de lejos."},
     {"Cómo aprendí a volar",
      "Todos dicen que el Cuidador me enseñó a volar. Mentira. Él tampoco sabía. Nos tiramos juntos del cerro y caímos de cabeza en las hojas. Se rio tanto que se le cayó la corona de hojas. Al otro día lo intentamos de nuevo. Y al otro. Al cuarto, el viento se apiadó de nosotros. Equivocarse también es volar un poquito.",
      "¡El Cuidador tampoco sabía volar! Caímos juntos en las hojas. Al cuarto día, el viento nos ayudó."},
     {"El vuelo que no fue",
      "Cuando aprendí a volar de verdad, le prometí llevarlo a ver todo desde arriba. «Otro día», me decía. «Hoy hay que regar. Hoy hay que barrer». Nunca dejaba que lo ayudaran. Al final no lo llevé yo: lo llevó Nimba. Mi hermano Prisma dice que no es culpa de nadie. Igual vuelo por los dos.",
      "Quise llevarlo a volar. Siempre decía «otro día». Nunca dejaba que lo ayudaran. Ahora vuelo por los dos."}},
    { /* Cristalino: la cueva. Maniático de afinar, quisquilloso. "Cantaba horrible". Enseña: escuchar de verdad ya es cuidar */
     {"Por qué cantan los cristales",
      "Los cristales guardan el eco de cada canción que se cantó aquí. Cada uno, afinado por mí. Do, re, mi… no, ese mi está bajo. Ya lo arreglo. El Cuidador venía a escucharlos sentado en esa piedra. Decía que oír de verdad ya es cuidar. Lo decía hablando encima de la música, eso sí. Siempre.",
      "Los cristales guardan cada canción. El Cuidador decía que oír de verdad ya es cuidar. ¡Pero hablaba encima!"},
     {"El río de abajo",
      "Debajo de la cueva corre un río que nadie ha visto. Suena en la. La perfecto: el único que no tengo que afinar. El Cuidador lo oyó una noche y se quedó callado una hora. ¡Una hora! Para él, un récord. Le pregunté qué pensaba. Me dijo: «Que hay cosas que cuidan sin que nadie las vea. Como este río». Entonces no entendí. Ahora… un poquito.",
      "Bajo la cueva corre un río que suena en la. El Cuidador lo escuchó callado una hora. ¡Un récord!"},
     {"Las gotas que tardan",
      "Aquí hay gotas que tardan cien años en caer. Cuando una cae, un cristal crece un pelito. Y si cae en la frente de un dragón de cristal… el dragón se duerme cien años. Así le pasó a Prisma. Mala puntería, la gota. El Cuidador se enojó con el techo y le habló una tarde entera. El techo no contestó. Los techos son así.",
      "Una gota que tarda cien años cayó en la frente de Prisma, y se durmió. ¡Mala puntería!"},
     {"El murciélago y el desafinado",
      "Había un murciélago que le tenía miedo al eco de su propia voz: chillaba y la cueva le contestaba, y él creía que eran monstruos. El Cuidador le cantó encima, desafinado, para que su eco no estuviera solo. Horrible. Los cristales brillaron de pura vergüenza. Y el murciélago, oyendo un eco todavía más feo que el suyo, se calmó. Todos ganamos. Bueno, mis oídos no.",
      "Un murciélago le temía a su eco. El Cuidador le cantó encima, desafinado. ¡Los cristales brillaron de vergüenza!"},
     {"Cada nota, guardada",
      "Cantaba horrible. Lo digo con todo respeto: horrible. Pero yo guardé cada nota suya en un cristal. Las desafinadas también. Sobre todo esas. La última vez vino a cantarle a Prisma y no le alcanzó la voz para el final. Dejó ese verso aquí, sin terminar. Yo no lo afiné. No me atreví. Esa parte… te la dejo a ti.",
      "Guardé cada nota del Cuidador, hasta las feas. Su último verso quedó sin terminar. Te lo dejo a ti."}},
    { /* Marea: la isla. Callada, firme. "Nunca cruzó solo: yo lo llevaba". Enseña: nadie debería cruzar solo */
     {"El lomo de la isla",
      "La isla es el lomo de una tortuga. Duerme. Hace siglos. Le crecieron árboles y un faro. La llamamos Abuela. No hagas ruido en la orilla: a veces respira. En el centro hay ocho piedras. Ahí el Cuidador dejó dormida la mitad de su luz. Esperando.",
      "La isla es una tortuga dormida. La llamamos Abuela. En las ocho piedras duerme una luz. Esperando."},
     {"El faro de piedritas",
      "El faro lo hicieron los barquitos de hoja. Cada uno traía una piedrita de la laguna. Tardaron un verano. El Cuidador apilaba las de arriba. Se subía a mi cola para alcanzar. Yo cuido que la luz no se apague. Nunca. Para que nadie se pierda de noche.",
      "Los barquitos de hoja hicieron el faro con piedritas. El Cuidador se subía a mi cola para alcanzar."},
     {"La concha que repite",
      "Las conchas de la Isla del Faro cuentan historias de olas. Cada una, distinta. Dicen que las pule la Pincoya, la que baila en la orilla cuando el mar está contento. Hay una que repite siempre lo mismo: «ya va a llegar». Es la voz del Cuidador. La dejó grabada una noche, mirando el agua. Nunca me dijo a quién esperaba. Yo guardo la concha. Por si acaso.",
      "Hay una concha que repite «ya va a llegar», con la voz del Cuidador. ¿A quién esperaba?"},
     {"Mi amiga Nimba",
      "Nimba es mi amiga. Pasa sobre la isla cuando el cielo está despejado. Es lenta. Sabia. Nunca se apura. El Cuidador decía que Nimba era una nube que aprendió a querer. Si eres cariñosa con todos, un día te llevará a pasear. A mí no me lleva. Cola de pez. Peso mucho.",
      "Nimba es una nube que aprendió a querer. Si eres cariñosa, te llevará a pasear. A mí no: peso mucho."},
     {"El cruce que no hice",
      "Nunca cruzó solo. Yo lo llevaba. Siempre. La última noche no me dejó. «Esta vez voy solo», dijo, y se subió al lomo de Nimba. Yo me quedé en la orilla. Debí ir igual. Nadie debería cruzar solo. Por eso te acompaño en el bote. Siempre. No discutas.",
      "La última noche no me dejó acompañarlo. Debí ir igual. Por eso te acompaño siempre. No discutas."}},
};

/* --- Nimba, la ballena de nubes: una historia por paseo (la única que vio que era chiquito) --- */
static const historia_t NIMBA_HISTORIAS[5] = {
    {"Lo que brilla en el musgo",
     "Desde arriba se ve lo que desde el suelo no. El anillo de las hadas es un círculo perfecto, hecho a pasitos de baile. En el centro brilla algo de madera, como una cuchara. Las hadas bailan alrededor para que nadie lo pise. Las cosas que alguien quiso mucho se quedan brillando, aunque nadie las use.",
     "Desde arriba se ve algo de madera en el anillo de las hadas. Lo que alguien quiso mucho sigue brillando."},
    {"La mano chiquita",
     "Una tarde una cometa subió tanto que me rozó la panza. La sostenía una mano muy chiquita. Sí: chiquita. Todos lo recuerdan grande, pero yo lo vi desde arriba. Soltó el hilo a propósito y me gritó: «¡Que vea el mundo!». La cometa todavía me cuenta lo que ve. Lo pequeño, mirado de cerca, siempre es grande.",
     "Yo vi la mano del Cuidador desde arriba. Era chiquita. Todos lo recuerdan grande, pero no lo era."},
    {"El espejo de la laguna",
     "Cuando paso sobre la laguna, alguien me saluda desde el agua: soy yo, con la sonrisa al revés. El Cuidador se reía de eso hasta llorar. Una noche dibujó estrellas en el agua para que mi reflejo no estuviera solo. Siguen ahí. Solo aparecen si las miras con cariño.",
     "El Cuidador dibujó estrellas en la laguna para que mi reflejo no estuviera solo."},
    {"El dragón dormido",
     "Bajo la cueva duerme un dragón de cristal. Se llama Prisma. Era su mejor amigo. Una gota lo durmió justo cuando más falta hacía. El Cuidador le cantó para despertarlo, pero la voz no le alcanzó. Yo tarareo al pasar, por si acaso. También desafino. Debe ser cosa de quienes quieren mucho.",
     "Prisma, el dragón, era su mejor amigo. Se durmió cuando más falta hacía. Yo le tarareo al pasar."},
    {"Su último paseo",
     "Una noche se subió a mi lomo sin decir nada. Era tan liviano. Cruzamos nubes y estrellas. Me dijo bajito: «Todo esto lo hice para que alguien lo cuidara». Y se quedó dormido mirando las estrellas. Yo di mil vueltas lentas para que no se terminara el cielo. Ese fue su último paseo. El tuyo es el primero de muchos.",
     "Su último paseo fue en mi lomo. Dijo: «Lo hice para que alguien lo cuidara», y se durmió con las estrellas."}};

/* --- Prisma, el dragón de cristal: ocho capítulos, uno por día, al tocarlo en la cueva (semanas 3 y 4) --- */
static const historia_t PRISMA_CAPITULOS[PET_PRISMA_CAPS] = {
    {"Cómo nos conocimos",
     "Yo era un montón de cristales que no sabía que era dragón. Él entró a la cueva cantando. Fatal. Lo digo con cariño: fatal. Los cristales se pusieron de acuerdo para sonar bonito, solo por él. De tanto ponerse de acuerdo… desperté. Fue la primera vez que algo me pidió afinarme.",
     "Yo era un montón de cristales. Él entró cantando fatal, y de tanto oírlo, desperté."},
    {"Las lecciones de afinar",
     "Le enseñé a afinar. Durante años. No aprendió nada. Él me enseñó a reírme. Aprendí a la primera. Creo que hicimos un mal negocio. Para él.",
     "Yo le enseñé a afinar y no aprendió. Él me enseñó a reírme, y aprendí al tiro."},
    {"La cuchara de palo",
     "Tenía una cuchara de palo para todo. Plantaba con ella. Revolvía con ella. Dirigía la orquesta de grillos con ella. Una vez intentó peinarme con ella. Soy de cristal. No tengo pelo. Insistió igual.",
     "Tenía una cuchara de palo para todo. ¡Hasta intentó peinarme! Soy de cristal."},
    {"Lo que nunca pedía",
     "Cuidaba el prado, el bosque, la laguna, el cerro, la cueva y la isla. Todo, él solo. Yo le decía: «Déjame la cueva a mí». Me contestaba con un chiste. Siempre el mismo, el de la papa. Nunca supe el final: se reía antes de llegar.",
     "Lo cuidaba todo solo. Si le ofrecías ayuda, te contaba un chiste."},
    {"La lucecita",
     "Con los años se enfermó. Empezó a apagarse despacio, como un farol al que se le acaba el aceite, y siguió cuidando igual. Yo lo vi. Y pensé: «Mañana le digo que descanse». Los dragones creemos que siempre hay mañana. Somos así de tontos.",
     "Se enfermó y se fue apagando, despacito. Yo pensé: «Mañana le digo». Siempre creí que había mañana."},
    {"La gota",
     "Entonces cayó la gota. Los dragones de cristal dormimos cien años cuando una gota nos toca la frente. Es la regla; no la inventé yo. Justo cuando él más me necesitaba, me dormí. Mala puntería, la gota. Mala suerte, la mía.",
     "Una gota me tocó la frente y me dormí cien años. Justo cuando él más me necesitaba."},
    {"La canción en sueños",
     "Vino a cantarme para despertarme. Lo oí en sueños. Desafinado, valiente, con muchas ganas. Llegó a la última parte… y la voz no le alcanzó. Dejó ese verso escondido entre los cristales, para que alguien lo terminara. Yo no desperté. Cien años llevo pensando en esa última nota.",
     "Me cantó para despertarme, pero no le alcanzó la voz. Dejó el último verso entre los cristales."},
    {"Lo que aprendí despierto",
     "Cuando desperté, él ya se había ido a dormir con las estrellas. Me enojé con la gota, con el techo, conmigo. Después entendí algo: él tampoco pidió ayuda. Ninguno de los dos supo. Perdonarse también se aprende. Despacio, como afinar. Yo estoy en eso. Gracias por tocar mis cristales.",
     "Al despertar, él ya dormía con las estrellas. Perdonarse también se aprende. Gracias por despertarme."},
};

/* --- Tilde, la tenca (con su pañuelo): sus chismes (mentira + verdad escondida). Los 8 primeros desde el principio; del 9 al 11, cuando ya conoce a
 *     todas las criaturas; el 12, solo cuando ya es la Guardiana --- */
static const historia_t TILDE_CHISMES[PET_TILDE_CHISMES] = {
    {"La corona de queso",
     "¿El Rey? Uy, lo conocí muchísimo. Era altísimo, tenía corona de queso y bigotes hasta el suelo. Bueno, quizás no tan alto. Quizás un poquito más bajo que yo. Quizás cabía en una taza. ¡Pero el queso es verdad!",
     "¡El Rey tenía corona de queso! Y era altísimo. Bueno… cabía en una taza."},
    {"La cuchara de diamantes",
     "Te cuento un secreto que nadie sabe. Nadie, nadie. El Rey tenía una cuchara de oro con diamantes. ¿Dónde está? Ni idea. Bueno, sí: entre el musgo, donde bailan las hadas. Y es de palo. Pero no le digas a nadie que te dije. Ni que es de palo.",
     "El Rey tenía una cuchara de diamantes. Bueno, de palo. Está donde bailan las hadas. ¡No le digas a nadie!"},
    {"Las lágrimas de Ondina",
     "Ondina dice que la laguna la lloró ella sola. ¡Ja! Yo estaba ahí. Bueno, no estaba. Pero me contaron que eran dos llorando. Uno chiquito, con un pañuelo enorme. ¡No lo andes contando!",
     "Ondina no lloró sola la laguna. Eran dos. Uno chiquito, con un pañuelo enorme."},
    {"El mejor volador",
     "Anemoi dice que es el mejor volador del mundo. El mejor volador del mundo soy yo, evidentemente. Él aprendió cayéndose en las hojas con el Rey. Los dos de cabeza. Yo vi todo desde una rama. Me reí tres días.",
     "Anemoi aprendió a volar cayéndose con el Rey. ¡Los dos de cabeza! Yo me reí tres días."},
    {"Los botones del abrigo",
     "¿Sabías que el Rey le regaló su abrigo a una roca? ¡A una roca! Yo quería ese abrigo. Tenía botones brillantes. Bueno, uno. Bueno, era una semilla. Pero brillaba si le daba el sol.",
     "El Rey le regaló su abrigo a una roca. ¡Yo lo quería! Tenía un botón brillante. Era una semilla."},
    {"Las galletas robadas",
     "Las galletas del Rey eran deliciosas. Mentira: eran carbón. Pero yo me las comía igual, porque las hacía con cariño. No le digas a Musguito: dice que yo me robaba las de la ofrenda. Me las robaba.",
     "Las galletas del Rey eran carbón. Igual me las comía, porque tenían cariño. Y sí, me las robaba."},
    {"El dragón que ronca",
     "El dragón de cristal ronca. Fuerte. Lo sé porque entré a la cueva a buscar cosas brillantes. Él era la cosa más brillante. No me lo pude llevar: pesa como cien tortugas. Dice que se durmió justo cuando no debía. Pobrecito. Igual ronca.",
     "Quise llevarme al dragón de cristal. ¡Pesa como cien tortugas! Y ronca."},
    {"La Abuela de abajo",
     "La isla es una tortuga. ¡En serio! Esta vez no miento. Bueno, casi nunca miento. Se llama Abuela Brizna y despierta de vez en cuando. Una vez le pregunté su edad y se durmió antes de contestar.",
     "¡La isla es una tortuga! Se llama Abuela Brizna. Le pregunté su edad y se durmió."},
    {"Un nombre de árbol",
     "El Rey tenía un nombre. Corto. Como de árbol. ¿Cuál era? Lo tengo en la punta del pico… ¿Roble? No. ¿Pino? Tampoco, Pino es el que ronca. Bah. Es lo único que se me ha olvidado en la vida. Eso y dónde dejé mi otra cuchara.",
     "El Rey tenía un nombre corto, como de árbol. ¿Cuál era? Se me olvidó."},
    {"Las manos más grandes",
     "Nimba dice que el Rey tenía una mano chiquita. ¡Qué disparate! Tenía las manos más grandes del mundo. Para abrazar. Bueno… eran chiquitas. Pero abrazaba grande. Eso cuenta, ¿no?",
     "El Rey tenía manos chiquitas. Pero abrazaba grande. Eso cuenta."},
    {"El sombrero que me robé",
     "Una vez le pregunté al Rey quién lo cuidaba a él. Me contestó con el chiste de la papa. Yo le dije: «Yo te cuido». Y me robé su sombrero para cuidárselo. Nunca me lo pidió de vuelta. Creo que entendió. Creo.",
     "Le dije al Rey: «Yo te cuido», y me robé su sombrero para cuidárselo. Creo que entendió."},
    {"El chisme más grande",
     "Te voy a contar el chisme más grande del mundo. El Rey, antes de irse, escondió un huevo. Un huevo que brillaba como… como tú, mira. Igualito. Qué raro. Bah, seguro me lo inventé. ¿Me lo inventé? Ya no sé.",
     "El Rey escondió un huevo que brillaba igualito a ti. ¿Me lo inventé? Ya no sé."},
};
/* la nota con que devuelve lo que se llevó: {O} es el objeto */
static const char *const TILDE_NOTAS[] = {
    "Te devuelvo tu {O}. Lo pedí prestado. Bueno, me lo llevé sin pedir. Pero lo cuidé muchísimo: lo pulí con el ala. - Tilde",
    "Aquí está tu {O}. Lo tuve en mi nido tres noches. Brillaba tanto que no me dejó dormir. Mejor lo cuidas tú. - Tilde",
    "Encontré esto tirado. ¿Es tuyo? Qué casualidad. Toma tu {O}. - Tilde, la más honesta del bosque",
    "Tu {O} me contó todos tus secretos. Mentira, no habla. Te lo devuelvo igual. - Tilde",
    "Te devuelvo tu {O} con una plumita de regalo. No es para que me perdones. Bueno, sí. - T.",
    "El Rey decía: «Lo que se cuida, vuelve». Yo no cuidé nada, pero tu {O} volvió igual. Toma. - Tilde",
};
#define N_TILDE_NOTAS (int)(sizeof TILDE_NOTAS / sizeof TILDE_NOTAS[0])

/* --- la Abuela Brizna: cinco recuerdos, más o menos uno por semana de juego. Para ella una semana es un año. El quinto: la pista del huevo
 *     (y le entrega la mitad del Corazón que dormía en su lomo) --- */
static const historia_t BRIZNA_RECUERDOS[PET_BRIZNA_RECUERDOS] = {
    {"Llegó en un huevo",
     "¿Mmm? ¿Quién anda ahí? Ah… hola, chiquita. ¿El Cuidador? Llegó en un huevo. Chiquitito. Lo empollé yo, creo. ¿O era una piedra? Estaba muy cansada ese siglo. Pero se parecía a ti. Tenía la misma manera de mirar las cosas… como si fueran nuevas.",
     "¿El Cuidador? Llegó en un huevo, chiquitito. Se parecía a ti. ¿O era una piedra? Se me olvidó."},
    {"Un mundo con una cuchara",
     "¿Otra vez tú? ¡Qué rápido pasan los años! Cuando yo era joven… hace nueve siglos… o diez… aquí no había nada. Solo piedras. Y un chiquitito con una cuchara, cavando. Le pregunté: «¿Qué haces?». Me dijo: «Un mundo». Me reí. Me quedé dormida riéndome. Desperté y había un bosque. No hay apuro para lo importante.",
     "¡Qué rápido pasan los años! Había solo piedras, y un chiquitito cavando con una cuchara: «Hago un mundo»."},
    {"Las ocho piedras",
     "¿Ya pasó otro año? Uf. Las ocho piedras de mi lomo me hacen cosquillas. Las puso él. Una por cada… ¿por cada qué era? Ah, sí. Una por cada lugar que cuidaba, y dos para el corazón. Dijo que algún día alguien vendría a sentarse en el medio. Que no me moviera. No me he movido. Bueno, un poquito, al bostezar.",
     "Las ocho piedras de mi lomo las puso él: una por cada lugar, y dos para el corazón."},
    {"Quién cuida al que cuida",
     "Otro año más… cómo vuelan. ¿Sabes qué me da pena, chiquita? Él cuidaba a todos y nadie lo cuidaba a él. Yo tampoco: estaba dormida. Si alguien quiere cuidarte, déjalo. Tú también eres parte del mundo. Eso. Ahora déjame dormir… otro año… o dos…",
     "Él cuidaba a todos y nadie lo cuidaba a él. Si alguien quiere cuidarte, déjalo."},
    {"Algo tibio y redondo",
     "Ya estoy vieja para guardar secretos. Esa última noche no dormí. Lo vi bajar de la ballena con algo en los brazos, envuelto en hojas. Tibio. Redondo. Lo escondió y volvió a subir, liviano. ¿Qué era? Se me olvidó. Pero era tibio… como tú. Toma. Esto dormía en mi lomo. Ya no lo necesito cuidar: ahora estás tú.",
     "Esa última noche escondió algo tibio y redondo, envuelto en hojas. Toma: esto dormía en mi lomo. Ahora estás tú."},
};
/* después del final: solo vuelve a saludar (su cumpleaños, la primavera) */
static const char *const BRIZNA_SALUDOS[] = {
    "¡Qué rápido pasan los años! Feliz cumpleaños, chiquita. Bueno… ¿es tu cumpleaños? Igual: feliz.",
    "Huele a primavera. Me desperté a mirar las flores. Ya me vuelvo a dormir… cuídate, chiquita.",
    "¿Otra vez tú? Qué bueno. Solo quería ver que estuvieras bien. Bostezo… hasta el otro año.",
};
#define N_BRIZNA_SALUDOS (int)(sizeof BRIZNA_SALUDOS / sizeof BRIZNA_SALUDOS[0])

/* --- las páginas sueltas del diario de Tilo (escritas a mano; firma con una cucharita, nunca con su nombre) ---
 *     0-3: al descubrir los cuatro secretos; 4: cuando conoce a las seis criaturas; 5: en la casita escondida;
 *     6: en el mirador del último paseo; 7: después del rito; 8 (v39): la carta del segundo final */
static const historia_t TILO_PAGINAS[PET_TILO_PAGINAS] = {
    {"Cosas por cuidar hoy",
     "Cosas por cuidar hoy: 1. Regar a Doña Pétalo. 2. Consolar a la nube (otra vez). 3. Arreglar el nido que se cayó. 4. Hornear galletas (no quemarlas). 5. No quemarlas. 6. Bueno, quemarlas un poco. Se me perdió la cuchara. Si alguien la encuentra, que la use: sirve para todo.",
     "Cosas por cuidar hoy: regar, consolar a la nube, hornear galletas (no quemarlas). Se me perdió la cuchara."},
    {"Seis maneras de consolar",
     "Seis maneras de consolar, para no olvidarlas: una tetera tibia. Un caracol que acompañe lento. Un farol en la ventana. Un pez que sonríe. Una escoba para barrer la pena. Y un abrazo, al final, porque es el más grande. Las dibujé en la laguna con el dedo. Me equivoqué de dedo tres veces.",
     "Seis maneras de consolar: tetera, caracol, farol, pez, escoba y abrazo. El abrazo va al final: es el más grande."},
    {"Querida cometa",
     "Querida cometa: te solté porque te quiero, no porque no te quiera. Eso es difícil de explicarle a una cometa. Si ves algo bonito allá arriba, tráeselo a quien te sostenga después de mí. P.D.: El chiste de la papa no tiene final. Por eso me río antes.",
     "Querida cometa: te solté porque te quiero. Si ves algo bonito allá arriba, tráeselo a quien te sostenga."},
    {"El verso que falta",
     "Hoy fui a cantarle a Prisma. Llegué casi hasta el final y se me acabó la voz. Dejé el último verso aquí, entre los cristales, sin terminar. Alguien con más voz que yo lo terminará. Ojalá cante desafinado. Así sabré que lo hizo con ganas.",
     "Fui a cantarle a Prisma y se me acabó la voz. Dejé el último verso entre los cristales. Ojalá alguien lo termine."},
    {"Quién me cuida a mí",
     "Hoy Musguito me preguntó quién me cuida a mí. Le conté el chiste de la papa. Me da vergüenza escribirlo: no sé qué contestar. Creo que me da miedo que todo dependa de mí. Y más miedo me da pedir ayuda. Mañana lo intento. (Llevo cien mañanas diciendo eso.)",
     "Musguito me preguntó quién me cuida a mí. No supe qué decir. Me da miedo pedir ayuda. Mañana lo intento."},
    {"Receta de galletas",
     "Receta de galletas de piñón: una taza de piñones molidos. Un poco de miel de ulmo. Mucho cariño. Hornear hasta que estén doradas. Ojo: «doradas» no es lo mismo que «negras». Me cuesta. Nota: la cama nueva me queda perfecta. Alguien dijo que parece de muñeca. Yo digo que parece de mi tamaño.",
     "Receta: piñones, miel de ulmo y mucho cariño. Hornear hasta que estén doradas (no negras). Mi cama me queda perfecta."},
    {"Desde el mirador",
     "Desde aquí se ve todo lo que cuidé. Es mucho para alguien tan chico, y estoy enfermo: ya no alcanzo a cuidarlo todo. Esta noche me voy con Nimba a mirar las estrellas de cerca. Antes tengo que dejar algo tibio en un lugar seguro, para que el mundo no dependa de uno solo. Ojalá llegue a buenas manos.",
     "Desde aquí se ve todo lo que cuidé. Estoy enfermo y ya no alcanzo. Esta noche me voy con Nimba."},
    {"Para quien cuide el huevo",
     "Si estás leyendo esto, el huevo llegó a buenas manos. Adentro iba la mitad del Corazón del Mundo: no se fue conmigo, la guardé ahí. Así el mundo tendrá que cuidarse entre varios: tú cuidas al huevo, y lo que nazca cuidará a los demás. Perdón por no haber pedido ayuda antes. Esta es mi manera de pedirla.",
     "Si lees esto, el huevo llegó a buenas manos. Adentro iba la mitad del Corazón. Así el mundo se cuida entre varios."},
    {"La última página",
     "Si estás leyendo esto, terminaste mi canción… Yo nunca supe pedir ayuda, y enfermé. Tú aprendiste a cuidarte y a cuidar. Gracias por enseñarle al mundo lo que yo no supe hacer. Firma: Peumo. PD: Búscame en las estrellas. Soy la cuchara.",
     "Terminaste mi canción. Tú aprendiste a cuidarte y a cuidar. Gracias. Firma: Peumo. PD: Búscame en las estrellas. Soy la cuchara."},
};

/* --- lo que dicen los animales (los cuenta ella): tres por animal, uno por acto; ficha = FAUNA_* o FAUNA_COUNT + ANIMAL_* --- */
typedef struct { uint8_t ficha; const char *txt, *corto; } frase_animal_t;
#define FA(a) (FAUNA_COUNT + (a))
static const frase_animal_t FRASES_ANIMAL[PET_ANIMAL_FRASES] = {
    {FA(ANIMAL_ARDILLA), "El monito del monte dice que el Rey escondía galletas quemadas por todo el bosque. ¡Todavía encuentra algunas!", "El monito del monte todavía encuentra galletas quemadas del Rey."},
    {FA(ANIMAL_ARDILLA), "El monito del monte dice que el Rey siempre le dejaba el piñón más grande… aunque a él le costaba levantarlo.", "Al Rey le costaba levantar un piñón grande."},
    {FA(ANIMAL_ARDILLA), "El monito del monte dice que, al final, el Rey ya no subía a los árboles. Decía que mirar desde abajo también era bonito.", "Al final el Rey ya no subía a los árboles."},
    {FA(ANIMAL_TOPO), "El topo dice que el Rey le abrió un hoyo en el techo con una cuchara de palo. Dice que nunca lo perdonó… bueno, un poquito.", "El Rey le abrió un hoyo al topo con su cuchara. Lo perdonó un poquito."},
    {FA(ANIMAL_TOPO), "El topo, gruñendo, dice que el Rey era el único que entraba a su túnel sin agacharse.", "El Rey entraba al túnel del topo sin agacharse."},
    {FA(ANIMAL_TOPO), "El topo dice que nadie bajaba a ver si el Rey estaba bien. «Yo tampoco», gruñó. Y se escondió.", "Nadie bajaba a ver si el Rey estaba bien."},
    {FA(ANIMAL_CONEJO), "El conejo dice que el Rey jugaba a perseguirlo y siempre perdía. ¡Pero se reía tanto!", "El Rey perdía siempre con el conejo, y se reía."},
    {FA(ANIMAL_CONEJO), "El conejo dice que el Rey saltaba con él… ¡y que no era más alto que él!", "¡El Rey no era más alto que el conejo!"},
    {FA(ANIMAL_CONEJO), "El conejo dice que al final el Rey ya no saltaba. Se sentaba a mirarlo, y aplaudía igual.", "Al final el Rey ya no saltaba, pero aplaudía."},
    {FAUNA_ZORRO, "El zorro me confesó que el Rey le dejaba fruta a propósito, para que no tuviera que robarla.", "El Rey le dejaba fruta al zorro para que no robara."},
    {FAUNA_ZORRO, "El zorro dice que una vez quiso robarle la cuchara al Rey. El Rey se la prestó. Le dio tanta vergüenza que la devolvió.", "El zorro quiso robar la cuchara y el Rey se la prestó."},
    {FAUNA_ZORRO, "El zorro dice que, cuando el Rey se enfermó, se dormía en cualquier parte. Él lo tapaba con hojas. Nunca se lo dijo a nadie.", "Cuando el Rey se enfermó, el zorro lo tapaba con hojas."},
    {FA(ANIMAL_GRILLO), "Los grillos dicen que el Rey los dirigía con una cuchara. Como orquesta. Una orquesta muy desordenada.", "El Rey dirigía a los grillos con una cuchara."},
    {FA(ANIMAL_GRILLO), "Los grillos dicen que todavía tocan la canción del Rey… desafinada, como a él le gustaba.", "Los grillos tocan la canción del Rey, desafinada."},
    {FA(ANIMAL_GRILLO), "Los grillos dicen que la canción del Rey tiene un final que nadie sabe tocar. Lo están esperando.", "Nadie sabe tocar el final de la canción del Rey."},
    {FAUNA_PAJARO, "El chincol dice que el Rey le silbaba al amanecer. Mal. Pero el sol salía igual.", "El Rey silbaba mal, pero el sol salía igual."},
    {FAUNA_PAJARO, "El chincol canta una melodía que se corta siempre en la misma parte. Dice que nadie sabe cómo termina.", "El chincol canta una canción que no termina."},
    {FAUNA_PAJARO, "El chincol dice que la última noche vio al Rey subir muy alto, en algo blanco y suave como una nube.", "El chincol vio al Rey subir en algo blanco como una nube."},
    {FA(ANIMAL_CARACOL), "El caracol dice que el Rey le ponía nombre a cada una de sus vueltas. Tiene muchas vueltas. Muchos nombres.", "El Rey le puso nombre a cada vuelta del caracol."},
    {FA(ANIMAL_CARACOL), "El caracol dice que el Rey era el único que lo esperaba sin apuro.", "El Rey esperaba al caracol sin apuro."},
    {FA(ANIMAL_CARACOL), "El caracol dice que, cuando se enfermó, el Rey caminaba tan despacio como él. Y que no se lo contó a nadie.", "Enfermo, el Rey caminaba tan despacio como el caracol."},
    {FA(ANIMAL_BUHO), "El chuncho dice que el Rey le preguntaba la hora de noche. El chuncho no sabe la hora. Le decía «ulú». El Rey le daba las gracias.", "El chuncho no sabe la hora, pero el Rey le daba las gracias igual."},
    {FA(ANIMAL_BUHO), "El chuncho dice que el Rey contaba estrellas y siempre perdía la cuenta en la treinta y siete.", "El Rey perdía la cuenta de las estrellas en la 37."},
    {FA(ANIMAL_BUHO), "El chuncho lo veía de noche, sentado solito, contando estrellas. Dice que nadie le preguntó nunca si estaba bien.", "Nadie le preguntó nunca al Rey si estaba bien."},
    {FA(ANIMAL_ERIZO), "El pichi dice que el Rey fue el primero en esperarlo quieto. Así se hicieron amigos.", "El Rey esperó quieto al pichi, y se hicieron amigos."},
    {FA(ANIMAL_ERIZO), "El pichi dice que el Rey le cabía en la sombra de una hoja de repollo. ¡Igual que él!", "El Rey cabía bajo una hoja de repollo."},
    {FA(ANIMAL_ERIZO), "El pichi dice que el Rey también se hacía bolita cuando se sentía enfermito… pero donde nadie lo viera.", "El Rey se hacía bolita cuando se sentía mal, a escondidas."},
    {FA(ANIMAL_TORTUGA), "La tortuga dice que su abuela duerme bajo la isla… y que ella sabe de dónde vino el Rey.", "La abuela de la tortuga duerme bajo la isla."},
    {FA(ANIMAL_TORTUGA), "La tortuga dice que su abuela ronca una vez por semana. Para ella, eso es una vez al año.", "La Abuela Brizna despierta una vez por semana."},
    {FA(ANIMAL_TORTUGA), "La tortuga dice que no hay apuro para lo importante. Dice que lo dice su abuela. Y que lo decía el Rey.", "No hay apuro para lo importante."},
    {FA(ANIMAL_CIERVO), "No dijo nada. Solo miró al cielo, hacia donde vuela Nimba… Creo que lo extraña.", "Miró al cielo, hacia Nimba. Creo que lo extraña."},
    {FA(ANIMAL_CIERVO), "El huemul no habla. Pero me llevó hasta un sendero del bosque que nunca había visto, y se fue.", "El huemul me mostró un sendero escondido."},
    {FA(ANIMAL_CIERVO), "El huemul se quedó quieto mirando la cima del cerro, de noche. Como esperando a alguien que no va a bajar.", "El huemul mira la cima del cerro, esperando."},
};
#undef FA

/* --- las invitaciones de las criaturas (son sus cartas): dos por cada cosa que proponen --- */
typedef struct { uint8_t criatura, cita; const char *txt; } invitacion_t;
static const invitacion_t INVITACIONES[] = {
    {CRI_MUSGUITO, CITA_PICNIC, "Hoy el musgo está suavecito y tibio… Traje un mantel de hojas y unas moras chiquititas. ¿Vienen a un picnic al prado? Si no es mucha molestia…"},
    {CRI_MUSGUITO, CITA_PICNIC, "Hice galletas de piñón con la receta del Cuidador. Salieron quemadas… como las de él. ¿Vienen igual al prado? Saben mejor acompañadas."},
    {CRI_MUSGUITO, CITA_PLANTAR, "Tengo una semilla chiquitita que solo crece si la plantan dos amigos juntos. ¿Me ayudan hoy en el prado? Yo traigo la cuchara."},
    {CRI_MUSGUITO, CITA_PLANTAR, "El prado me pidió flores nuevas… bajito, pero me lo pidió. Yo pongo la semilla y ustedes el cariño. ¿Vienen hoy?"},
    {CRI_LUMBRE, CITA_ESCONDIDAS, "Esta noche apago mi luz y me escondo entre los árboles. Búsquenme sin prisa. Lo bonito de esconderse es que alguien te encuentra."},
    {CRI_LUMBRE, CITA_ESCONDIDAS, "El bosque tiene escondites nuevos. El Cuidador me buscaba siempre en el mismo… y siempre me encontraba. Vengan a jugar conmigo."},
    {CRI_LUMBRE, CITA_LUCIERNAGAS, "Las luciérnagas practican su baile esta tarde. Les falta alguien que se equivoque con gracia. ¿Vienen?"},
    {CRI_LUMBRE, CITA_LUCIERNAGAS, "Hoy encenderé todas las luces del bosque, como cuando el Cuidador se sentaba a mirarlas sin decir nada. Vengan a bailar con nosotras."},
    {CRI_ONDINA, CITA_PESCAR, "¡Los peces andan juguetones y yo ando emocionadísima! ¿Vienen a pescar? Les guardo la mejor orilla. Si no vienen, lloro. Un poquito. Bueno, mucho."},
    {CRI_ONDINA, CITA_PESCAR, "La laguna está quietita y brillante, como el día en que el Cuidador se sentó a mi lado. ¡Perfecto para pescar! Los espero en la orilla."},
    {CRI_ONDINA, CITA_BARQUITOS, "¡Carrera de barquitos de hoja! Ya hice dos. El mío se llama «Tormenta Furiosa». El de ustedes, «Bote Lento». ¡Es broma! ¡Vengan!"},
    {CRI_ONDINA, CITA_BARQUITOS, "Doblé barquitos con las hojas más bonitas, como los que hacía el Cuidador. A él se le hundían todos. ¿Echamos una carrera en la laguna?"},
    {CRI_VENTOLIN, CITA_COMETA, "¡Hoy sopla el mejor viento del siglo! Lo sé porque lo soplé yo. Traigan las ganas, que yo pongo el viento para la cometa."},
    {CRI_VENTOLIN, CITA_COMETA, "Le hice cosquillas a las nubes y prometieron viento. El Cuidador soltaba aquí sus cometas. ¿Elevamos una? Ustedes sostienen, yo presumo."},
    {CRI_VENTOLIN, CITA_VOLAR_HOJAS, "¡A atrapar hojas en el viento! En el cerro vuelan más alto que en ningún lado. Más alto que yo, no. Pero casi."},
    {CRI_VENTOLIN, CITA_VOLAR_HOJAS, "Voy a soplar un remolino de hojas, como le gustaba al Cuidador. Él siempre caía de cabeza en el montón. ¿Vienen?"},
    {CRI_CRISTALINO, CITA_MUSICA, "Los cristales están de buen humor y casi afinados. Casi. ¿Vienen a hacer música? Prometo no corregirlos. Mucho."},
    {CRI_CRISTALINO, CITA_MUSICA, "Afiné cada cristal de la cueva, como cuando venía el Cuidador. Hoy toco yo y ustedes bailan. Si desafinan, finjo que no oí."},
    {CRI_CRISTALINO, CITA_TESORO, "Escondí un tesoro brillante en la cueva. Bien escondido. Ordenado por colores. Si vienen hoy, les ayudo a buscarlo."},
    {CRI_CRISTALINO, CITA_TESORO, "En la cueva hay algo que brilla y no es mío. Creo que lo dejó el Cuidador. Está mal guardado y me pone nervioso. ¿Me ayudan?"},
    {CRI_MAREA, CITA_ESTRELLAS, "Esta noche hay muchas estrellas sobre la isla. Vengan a contarlas. Yo traigo el bote."},
    {CRI_MAREA, CITA_ESTRELLAS, "Las estrellas quieren dibujos nuevos. El Cuidador los inventaba. Vengan. Ayuden."},
    {CRI_MAREA, CITA_FARO, "El faro necesita luz para los barquitos. ¿Me ayudan a encenderlo hoy? Los espero en la orilla."},
    {CRI_MAREA, CITA_FARO, "La lámpara del faro está dormida. Él la encendía cada noche. Hoy la encendemos juntos. Vengan."},
};
